<?php
require __DIR__ . '/admin-common.php'; $pdo=db(); admin_ready($pdo); admin_require_login();
$stats=[]; $errors=[];
try {$stats['sellers']=(int)$pdo->query("SELECT COUNT(*) FROM sellers")->fetchColumn(); $stats['active_sellers']=(int)$pdo->query("SELECT COUNT(*) FROM sellers WHERE status='active'")->fetchColumn();} catch(Throwable $e){$stats['sellers']=$stats['active_sellers']=0;$errors[]='Seller table unavailable';}
try {$stats['products']=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(); $stats['published']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE status='active'")->fetchColumn();} catch(Throwable $e){$stats['products']=$stats['published']=0;$errors[]='Products table unavailable';}
try {$fin=admin_order_financials($pdo);} catch(Throwable $e){$fin=['orders_count'=>0,'order_value'=>0,'delivery_total'=>0,'sold_qty'=>0,'seller_revenue'=>0];$errors[]='Order tables unavailable';}
$views=(int)$pdo->query("SELECT COUNT(*) FROM eb_analytics_events WHERE event_type='page_view'")->fetchColumn();
$visitors=(int)$pdo->query("SELECT COUNT(DISTINCT visitor_key) FROM eb_analytics_events WHERE event_type='page_view'")->fetchColumn();
$logins=(int)$pdo->query("SELECT COUNT(*) FROM eb_analytics_events WHERE event_type='seller_login'")->fetchColumn();
$recent=$pdo->query("SELECT e.event_type,e.visitor_key,e.page_path,e.visitor_label,e.created_at,s.name seller_name FROM eb_analytics_events e LEFT JOIN sellers s ON s.id=e.seller_id ORDER BY e.created_at DESC LIMIT 80")->fetchAll();
$sellers=$pdo->query("SELECT s.id,s.name,s.email,s.status,s.created_at,COALESCE(p.published_count,0) published_count,COALESCE(x.sold_count,0) sold_count,COALESCE(x.revenue,0) revenue,COALESCE(x.delivery_fee,0) delivery_fee FROM sellers s LEFT JOIN (SELECT seller_id,COUNT(*) published_count FROM products WHERE status='active' GROUP BY seller_id) p ON p.seller_id=s.id LEFT JOIN (SELECT i.seller_id,SUM(CASE WHEN o.status<>'Cancelled' THEN i.quantity ELSE 0 END) sold_count,SUM(CASE WHEN o.status<>'Cancelled' THEN i.unit_price*i.quantity ELSE 0 END) revenue,SUM(CASE WHEN o.status<>'Cancelled' THEN COALESCE(o.delivery_charge,0) ELSE 0 END) delivery_fee FROM eb_order_items i JOIN eb_orders o ON o.id=i.order_id WHERE i.seller_id IS NOT NULL GROUP BY i.seller_id) x ON x.seller_id=s.id ORDER BY revenue DESC,s.created_at DESC LIMIT 100")->fetchAll();
$products=$pdo->query("SELECT p.id,p.name,p.category,p.price,p.stock,p.status,p.view_count,p.created_at,s.name seller_name,s.email seller_email,COALESCE((SELECT SUM(i.quantity) FROM eb_order_items i JOIN eb_orders o ON o.id=i.order_id WHERE i.product_id=p.id AND o.status<>'Cancelled'),0) sold FROM products p LEFT JOIN sellers s ON s.id=p.seller_id ORDER BY p.created_at DESC LIMIT 100")->fetchAll();
$orders=$pdo->query("SELECT o.id,o.order_code,o.customer_name,o.customer_email,o.status,o.total,o.delivery_charge,o.created_at,COALESCE((SELECT SUM(i.unit_price*i.quantity) FROM eb_order_items i WHERE i.order_id=o.id),0) item_subtotal,COALESCE((SELECT SUM(i.quantity) FROM eb_order_items i WHERE i.order_id=o.id),0) item_count FROM eb_orders o ORDER BY o.created_at DESC LIMIT 100")->fetchAll();
$recentOrders=(int)$pdo->query("SELECT COUNT(*) FROM eb_orders WHERE created_at >= DATE_SUB(NOW(),INTERVAL 30 DAY)")->fetchColumn();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EasyBuy Admin Dashboard</title><style>
:root{--blue:#245ce7;--ink:#172033;--muted:#6d7890;--line:#e7ebf2;--bg:#f4f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:14px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink)}a{color:inherit;text-decoration:none}.layout{display:grid;grid-template-columns:245px 1fr;min-height:100vh}.side{background:#111b30;color:#dfe7f8;padding:24px 16px}.logo{font-size:21px;font-weight:850;letter-spacing:.04em;padding:4px 12px 30px;color:white}.logo span{color:#79a1ff}.nav{display:grid;gap:7px}.nav a{padding:12px 14px;border-radius:10px;color:#bdc8df}.nav a:hover,.nav a.active{background:#263b62;color:white}.sidefoot{position:sticky;top:85vh;margin:35px 12px 0;color:#8fa0bf;font-size:12px}.main{padding:28px;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:24px}.top h1{font-size:28px;margin:0}.top p{margin:4px 0;color:var(--muted)}.pill{padding:9px 13px;border-radius:10px;background:white;border:1px solid var(--line)}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px;margin-bottom:22px}.stat,.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:19px;box-shadow:0 5px 18px #142b4b05}.stat .label{color:var(--muted);font-size:13px}.stat .num{font-size:28px;font-weight:800;margin:8px 0 2px;letter-spacing:-.03em}.stat .hint{font-size:12px;color:#8290a7}.panels{display:grid;grid-template-columns:1.25fr .75fr;gap:16px;margin-bottom:18px}.panel{margin-bottom:18px;overflow:hidden}.panelhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.panel h2{font-size:17px;margin:0}.search{padding:9px 11px;border:1px solid var(--line);border-radius:9px;max-width:220px;width:100%;font:inherit}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:12px 13px;border-bottom:1px solid #edf0f5;font-size:12.5px}th{background:#f8faff;color:#6d7890;font-size:11px;text-transform:uppercase;letter-spacing:.045em}tr:last-child td{border-bottom:0}.muted{color:var(--muted)}.tag{display:inline-block;padding:4px 8px;border-radius:99px;background:#edf3ff;color:#2755bb;font-size:11px}.tag.green{background:#e8f8ef;color:#137744}.tag.red{background:#fff0ef;color:#b43e35}.hidden{display:none!important}.section{scroll-margin-top:20px}.bar{display:flex;height:10px;background:#edf1f8;border-radius:99px;overflow:hidden;margin:13px 0}.bar span{background:var(--blue);height:100%}.metricrow{display:flex;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid #eef1f6}.metricrow:last-child{border-bottom:0}.notice{background:#fff8e6;border:1px solid #f5dfa0;padding:12px 14px;border-radius:11px;margin-bottom:16px;color:#78530b}.foot{color:#8b96aa;font-size:12px;text-align:right;padding:8px}@media(max-width:1100px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.panels{grid-template-columns:1fr}}@media(max-width:720px){.layout{grid-template-columns:1fr}.side{padding:12px}.logo{padding:8px 10px 13px}.nav{grid-template-columns:repeat(3,minmax(0,1fr))}.nav a{font-size:12px;padding:9px;text-align:center}.sidefoot{display:none}.main{padding:16px}.top{align-items:flex-start;flex-direction:column}.top h1{font-size:23px}.cards{gap:9px}.stat{padding:13px}.stat .num{font-size:23px}.stat .label{font-size:12px}.panel{padding:13px}}
</style></head><body><div class="layout"><aside class="side"><div class="logo">EASY<span>BUY</span> <small style="font-size:11px;color:#93a6ca">ADMIN</small></div><nav class="nav"><a class="active" href="#overview">▦ Overview</a><a href="#sellers">♙ Sellers</a><a href="#products">▤ Products</a><a href="#orders">▣ Orders & sales</a><a href="#visits">◉ Visitors</a><a href="admin-logout.php">↪ Sign out</a></nav><div class="sidefoot">Private store analytics<br>Signed in as <?=admin_e($_SESSION['admin_username']??'admin')?></div></aside><main class="main"><header class="top"><div><h1>Store overview</h1><p>Live totals from your EasyBuy MySQL database.</p></div><div class="pill">Updated <?=date('d M Y, h:i A')?> · <a href="adminindex.php" style="color:var(--blue);font-weight:700">Refresh</a></div></header>
<?php if($errors):?><div class="notice">Some database sections could not load: <?=admin_e(implode(', ',$errors))?>. Check that the EasyBuy database has been imported.</div><?php endif;?>
<section id="overview" class="section"><div class="cards"><article class="stat"><div class="label">Total products</div><div class="num"><?=number_format($stats['products'])?></div><div class="hint"><?=number_format($stats['published'])?> currently published</div></article><article class="stat"><div class="label">Seller accounts</div><div class="num"><?=number_format($stats['sellers'])?></div><div class="hint"><?=number_format($stats['active_sellers'])?> active sellers</div></article><article class="stat"><div class="label">Products sold</div><div class="num"><?=number_format($fin['sold_qty'])?></div><div class="hint"><?=number_format($recentOrders)?> orders in last 30 days</div></article><article class="stat"><div class="label">Seller product sales</div><div class="num"><?=admin_money($fin['seller_revenue'])?></div><div class="hint">Non-cancelled seller items</div></article><article class="stat"><div class="label">Orders placed</div><div class="num"><?=number_format((int)$fin['orders_count'])?></div><div class="hint">All recorded orders</div></article><article class="stat"><div class="label">Order value</div><div class="num"><?=admin_money($fin['order_value'])?></div><div class="hint">Excludes cancelled orders</div></article><article class="stat"><div class="label">Delivery charges</div><div class="num"><?=admin_money($fin['delivery_total'])?></div><div class="hint">Estimated from order totals where needed</div></article><article class="stat"><div class="label">Page views</div><div class="num"><?=number_format($views)?></div><div class="hint"><?=number_format($visitors)?> distinct browser sessions · <?=number_format($logins)?> seller logins</div></article></div>
<div class="panels"><section class="panel"><div class="panelhead"><h2>Store activity</h2><span class="tag">All time</span></div><div class="metricrow"><span class="muted">Published products</span><strong><?=number_format($stats['published'])?></strong></div><div class="bar"><span style="width:<?= $stats['products']?min(100,round($stats['published']/$stats['products']*100)):0 ?>%"></span></div><div class="metricrow"><span class="muted">Active sellers</span><strong><?=number_format($stats['active_sellers'])?></strong></div><div class="bar"><span style="width:<?= $stats['sellers']?min(100,round($stats['active_sellers']/$stats['sellers']*100)):0 ?>%"></span></div><div class="metricrow"><span class="muted">Unique browser sessions recorded</span><strong><?=number_format($visitors)?></strong></div><div class="metricrow"><span class="muted">Seller login events</span><strong><?=number_format($logins)?></strong></div></section><section class="panel"><div class="panelhead"><h2>What the numbers mean</h2></div><p class="muted">Sales exclude cancelled orders. Seller earnings are calculated from seller-linked product line items, before any platform commission (none is configured here).</p><p class="muted">Delivery charges use the saved fee when available; older orders are estimated as order total minus item subtotal.</p><p class="muted">Anonymous visitors are shown by a random session key, not by real name. Sellers are identifiable after they log in.</p></section></div></section>
<section id="sellers" class="panel section"><div class="panelhead"><h2>Seller performance</h2><input class="search" data-filter="sellerTable" placeholder="Search seller name/email"></div><div class="tablewrap"><table id="sellerTable"><thead><tr><th>Seller</th><th>Status</th><th>Published</th><th>Sold quantity</th><th>Product sales</th><th>Delivery fees on orders*</th><th>Joined</th></tr></thead><tbody><?php foreach($sellers as $s):?><tr><td><strong><?=admin_e($s['name'])?></strong><br><span class="muted"><?=admin_e($s['email'])?></span></td><td><span class="tag <?= $s['status']==='active'?'green':'red' ?>"><?=admin_e($s['status'])?></span></td><td><?=number_format((int)$s['published_count'])?></td><td><?=number_format((int)$s['sold_count'])?></td><td><strong><?=admin_money($s['revenue'])?></strong></td><td><?=admin_money($s['delivery_fee'])?></td><td><?=admin_e(date('d M Y',strtotime($s['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><p class="muted">*Delivery fees are order-level amounts, not seller earnings; a shared order may contain items from multiple sellers.</p></section>
<section id="products" class="panel section"><div class="panelhead"><h2>Product catalogue</h2><input class="search" data-filter="productTable" placeholder="Search product or seller"></div><div class="tablewrap"><table id="productTable"><thead><tr><th>Product</th><th>Seller</th><th>Category</th><th>Price</th><th>Stock</th><th>Sold</th><th>Views</th><th>Status</th><th>Published date</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><strong><?=admin_e($p['name'])?></strong><br><span class="muted">#<?=admin_e($p['id'])?></span></td><td><?=admin_e($p['seller_name']??'—')?><br><span class="muted"><?=admin_e($p['seller_email']??'')?></span></td><td><?=admin_e($p['category'])?></td><td><?=admin_money($p['price'])?></td><td><?=number_format((int)$p['stock'])?></td><td><?=number_format((int)$p['sold'])?></td><td><?=number_format((int)$p['view_count'])?></td><td><span class="tag <?= $p['status']==='active'?'green':'red' ?>"><?=admin_e($p['status'])?></span></td><td><?=admin_e(date('d M Y',strtotime($p['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section id="orders" class="panel section"><div class="panelhead"><h2>Orders & delivery charges</h2><input class="search" data-filter="orderTable" placeholder="Search order/customer"></div><div class="tablewrap"><table id="orderTable"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Item subtotal</th><th>Delivery charge</th><th>Order total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $o):$fee=(float)$o['delivery_charge']>0?(float)$o['delivery_charge']:max(0,(float)$o['total']-(float)$o['item_subtotal']);?><tr><td><strong><?=admin_e($o['order_code'])?></strong></td><td><?=admin_e($o['customer_name'])?><br><span class="muted"><?=admin_e($o['customer_email'])?></span></td><td><?=number_format((int)$o['item_count'])?></td><td><?=admin_money($o['item_subtotal'])?></td><td><?=admin_money($fee)?></td><td><strong><?=admin_money($o['total'])?></strong></td><td><span class="tag <?= $o['status']==='Cancelled'?'red':($o['status']==='Delivered'?'green':'') ?>"><?=admin_e($o['status'])?></span></td><td><?=admin_e(date('d M Y, h:i A',strtotime($o['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section id="visits" class="panel section"><div class="panelhead"><h2>Recent visits & login activity</h2><input class="search" data-filter="visitTable" placeholder="Search page, email, session"></div><p class="muted">Shows the latest 80 tracked events. A seller email appears after login; anonymous sessions are pseudonymous IDs.</p><div class="tablewrap"><table id="visitTable"><thead><tr><th>Event</th><th>Visitor</th><th>Page</th><th>Time</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><span class="tag <?= $r['event_type']==='seller_login'?'green':'' ?>"><?=admin_e(str_replace('_',' ',$r['event_type']))?></span></td><td><?=admin_e($r['visitor_label']?:($r['seller_name']?:('Visitor '.substr(hash('sha256',$r['visitor_key']),0,10))))?></td><td><?=admin_e($r['page_path'])?></td><td><?=admin_e(date('d M Y, h:i:s A',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></section><div class="foot">EasyBuy Admin · Database-backed report · Refresh to load latest data</div></main></div><script>document.querySelectorAll('[data-filter]').forEach(function(input){input.addEventListener('input',function(){var table=document.getElementById(input.dataset.filter),q=input.value.toLowerCase();table.querySelectorAll('tbody tr').forEach(function(row){row.classList.toggle('hidden',!row.innerText.toLowerCase().includes(q));});});});</script></body></html>
